// Weekday digest from the invoice log: approved bills coming due, and invoices still waiting on a person.
const S = $('Settings').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.status);
const today = new Date().toISOString().slice(0, 10);
const days = (a, b) => Math.round((new Date(a) - new Date(b)) / 86400000);
const money = (n) => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const within = Number(S.dueSoonDays || 7);

// Keep the latest row per vendor and invoice number, so a resubmitted invoice is not listed twice.
const latest = {};
for (const r of rows) latest[(r.vendor_key || r.vendor_name) + '|' + (r.invoice_number_key || r.invoice_number)] = r;
const list = Object.values(latest);

const unpaid = (r) => !/^(y|yes|true|paid|x)$/i.test(String(r.paid || '').trim());
const due = list.filter((r) => /^approved/.test(r.status) && unpaid(r) && r.due_date && days(r.due_date, today) <= within)
  .sort((a, b) => String(a.due_date).localeCompare(String(b.due_date)));
const waiting = list.filter((r) => /^(held|no answer)/.test(r.status) && days(today, String(r.logged_at).slice(0, 10)) <= 14);
if (!due.length && !waiting.length) return [];

const line = (r) => '• ' + r.vendor_name + ' ' + r.invoice_number + '  ' + r.currency + ' ' + money(r.total);
const parts = [];
if (due.length) {
  const total = due.reduce((a, r) => a + Number(r.total || 0), 0);
  parts.push('*Approved and due within ' + within + ' days: ' + due.length + ' (' + money(total) + ')*\n' +
    due.map((r) => line(r) + ', due ' + r.due_date + (days(r.due_date, today) < 0 ? ' (overdue)' : '')).join('\n'));
}
if (waiting.length) parts.push('*Still waiting on someone: ' + waiting.length + '*\n' + waiting.map((r) => line(r) + ' (' + r.status + ')').join('\n'));
return [{ json: { text: 'Accounts payable for ' + today + '\n\n' + parts.join('\n\n') + '\n\nMark a bill paid by typing yes in the paid column of the log.' } }];
